mapper.select:
SELECT S.ORDER_ID as orderId, '${effective}' as orderStatus, PP.PORTFOLIO_NAME ||'(' || PP.PORTFOLIO_ID ||')' as portfolioId, PP.PARENT_PORTFOLIO_ID ACT_PORTFOLIO_ID, PP.PORTFOLIO_NAME as portfolioName, case S.PS when '${IE_FLAG_02}' then S.MY_ACCT_NO else S.COUNTER_ACCT_NO end as myAcctNo, case S.PS when '${IE_FLAG_02}' then S.COUNTER_ACCT_NO else S.MY_ACCT_NO end as counterAcctNo, T.PS as payType, S.SETTLE_AMT as settleAmt, S.SETTLE_DATE as settleDate, T.TRADE_ID as tradeId, null as workflowId,
PP.PORTFOLIO_ID portfolioIdLink
FROM STL_DVP_ORDERS S LEFT JOIN STL_DVP_TRADE_MATCH SDTM ON S.ORDER_ID = SDTM.ORDER_ID LEFT JOIN TRD_PRODUCT_DEAL T ON T.TRADE_ID = SDTM.TRADE_ID LEFT JOIN PTL_TRADE PT ON T.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND T.IS_CANCEL = #{yesNo_no} AND T.TRADE_STATUS = #{TRADE_STATUS_01}
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND ((S.COUNTER_ACCT_NO = #{counterAcctNo} AND S.PS = '02') OR (S.MY_ACCT_NO = #{counterAcctNo} AND S.PS = '01'))
AND ((S.COUNTER_ACCT_NO = #{myAcctNo} AND S.PS = '01') OR (S.MY_ACCT_NO = #{myAcctNo} AND S.PS = '02'))
AND T.PS = #{payType}
AND S.SETTLE_DATE BETWEEN TO_DATE(#{dataDateStart},'YYYY-MM-DD') AND TO_DATE(#{dataDateEnd},'YYYY-MM-DD')
AND T.PS IN
#{item}
UNION ALL
SELECT S.ORDER_ID as orderId, '${revoked}' as orderStatus, PP.PORTFOLIO_NAME ||'(' || PP.PORTFOLIO_ID ||')' as portfolioId, null ACT_PORTFOLIO_ID, PP.PORTFOLIO_NAME as portfolioName, case S.PS when '${IE_FLAG_02}' then S.MY_ACCT_NO else S.COUNTER_ACCT_NO end as myAcctNo, case S.PS when '${IE_FLAG_02}' then S.COUNTER_ACCT_NO else S.MY_ACCT_NO end as counterAcctNo, T.PS as payType, S.SETTLE_AMT as settleAmt, S.SETTLE_DATE as settleDate, T.TRADE_ID as tradeId, null as workflowId,
PP.PORTFOLIO_ID portfolioIdLink
FROM STL_DVP_ORDERS S LEFT JOIN STL_DVP_TRADE_MATCH SDTM ON S.ORDER_ID = SDTM.ORDER_ID LEFT JOIN TRD_PRODUCT_DEAL T ON T.TRADE_ID = SDTM.TRADE_ID LEFT JOIN PTL_TRADE PT ON T.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND T.IS_CANCEL = #{yesNo_no} AND T.TRADE_STATUS = #{TRADE_STATUS_03}
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND S.COUNTER_ACCT_NO = #{counterAcctNo}
AND S.MY_ACCT_NO = #{myAcctNo}
AND T.PS = #{payType}
AND S.SETTLE_DATE BETWEEN TO_DATE(#{dataDateStart},'YYYY-MM-DD') AND TO_DATE(#{dataDateEnd},'YYYY-MM-DD')
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND T.PS IN
#{item}
order by settleDate desc, portfolioId

SELECT P.ACCT_NO id, S.ACCT_NAME text FROM PTL_CAPACCT_INFO P LEFT JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO AND P.CCY = S.CCY
AND (P.ACCT_NO LIKE CONCAT('%',CONCAT(#{search},'%')) OR S.ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND P.PORTFOLIO_ID = #{portfolioId}
AND P.ACCT_TYPE = #{acctType}
AND P.CCY = #{ccy}

SELECT
	B.TRD_ACCT_ID id,
	C.ACCT_NAME text
FROM PTL_SEC_ACCT A
INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
INNER JOIN STL_CAPACCT_INFO C on B.TRD_ACCT_ID = C.ACCT_NO

INNER JOIN PTL_CAPACCT_INFO D on B.TRD_ACCT_ID = D.ACCT_NO



		AND (B.TRD_ACCT_ID LIKE CONCAT('%',CONCAT(#{search},'%'))
		OR C.ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))


		AND A.PORTFOLIO_ID = #{portfolioId}


		AND B.REGIST_ORG = #{REGIST_ORG}


		AND C.CCY = #{ccy}



		AND D.PORTFOLIO_ID = #{portfolioId}


		AND D.ACCT_TYPE = #{acctType}

SELECT
	max(SEQNO)
FROM
PTL_CASH_POSITION_FLOW


		AND ORDER_ID = #{tradeId}


		AND HODING_TYPE=#{hodeType}
